LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
S523='https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=2729'
FUNG='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/2024/30092024-Recurso-em-sentido-estrito-pode-ser-aceito-como-apelacao-e-vice-versa--observados-os-pressupostos-legais.aspx'
JURY='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias-antigas/2019/Depois-do-juri-execucao-da-pena--limites-recursais-e-revisao-criminal.aspx'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(563,'Nulidade pressupõe prejuízo à acusação ou defesa, com exame da garantia e natureza do vício.', ['Evitar anulação por formalismo sem consequência.', 'Súmula523/STF distingue falta de defesa e mera deficiência.', 'Ausência completa de defesa não se equipara a simples inconformismo técnico.'], 'Não usar regra de prejuízo para validar processo totalmente sem defesa.', 'Erro de forma sem consequência relevante é analisado à luz da finalidade e prejuízo.', 'Falta absoluta de defensor tem tratamento distinto de discordar da estratégia adotada.', ['Qualquer erro formal anula automaticamente? Não.', 'Falta de defesa e deficiência são idênticas? Não.'], 'Prejuízo processual','Efeito concreto do vício sobre garantia processual.',[S523])
add(564,'Rol de nulidades protege competência, legitimidade, defesa, prova essencial, atos de julgamento e fundamentação, com remissões históricas.', ['Decisão sem fundamentação: incisoV, Lei13964/2019.', 'Distinguir falta de defensor e deficiência.', 'Libelo/contrariedade e curador menor de21 pertencem à redação histórica, não requisitos atuais gerais.', 'Contravenção não restaura ação acusatória policial por portaria.', 'Júri: composição, incomunicabilidade e quesitos seguem rito atual.'], 'Não gerar treino literal de libelo, curador só por idade de vinte anos ou acusação policial; integrar reformas e Constituição.', 'Sentença sem razões é examinada como decisão carente de fundamentação.', 'Acusado de vinte anos não recebe curador apenas por remissão residual antiga; defesa técnica permanece.', ['Falta de fundamentação consta do rol? Sim.', 'Libelo é requisito geral atual do júri? Não.'], 'Nulidades e reformas','Garantias essenciais lidas com as normas atuais.',[S523])
add(565,'Parte não pode invocar vício que causou/contribuiu ou formalidade de interesse exclusivo da outra.', ['Lealdade processual e finalidade da garantia.', 'Não converter regra em renúncia automática a toda garantia essencial.'], 'Examinar origem e interesse do vício; não permitir fabricar nulidade para lucrar com própria conduta.', 'Parte cria irregularidade deliberada e tenta usá-la em benefício: examina-se vedação.', 'Falta de defesa imposta pelo juízo não vira vício causado pelo réu só porque ele permaneceu em silêncio.', ['Causar vício autoriza aproveitá-lo livremente? Não.', 'Silêncio significa causar falta de defesa técnica? Não.'], 'Vedação de aproveitamento próprio','Limite ligado à responsabilidade e interesse na formalidade.')
add(566,'Ato sem influência na apuração relevante ou decisão não é anulado apenas pela irregularidade.', ['Relacionar vício e consequência.', 'Preservar atos úteis sem negar garantia essencial.'], 'Não chamar violação decisiva de mero detalhe sem demonstrar ausência de influência.', 'Erro material sem impacto na identificação ou defesa não produz anulação automática.', 'Supressão de prova defensiva relevante pode influir e exige exame real.', ['Irregularidade sem influência sempre anula? Não.', 'Influência relevante precisa ser analisada? Sim.'], 'Influência do vício','Relação entre irregularidade e processo decisório.')
add(567,'Incompetência anula atos decisórios no regime do artigo e exige remessa ao juízo competente.', ['Não apagar automaticamente toda prova independente.', 'Examinar natureza e efeitos da incompetência no caso.', 'Garantias de obtenção da prova permanecem.'], 'A regra não torna válida prova ilícita nem dispensa analisar atos dependentes.', 'Declarada incompetência, autos seguem ao órgão adequado e decisões são examinadas.', 'Depoimento regularmente documentado não desaparece por mera suposição de que tudo é nulo.', ['Remessa ao competente é prevista? Sim.', 'Artigo valida prova ilícita? Não.'], 'Efeito da incompetência','Consequência processual delimitada pelo ato e regime.')
add(568,'Ilegitimidade do representante pode ser sanada por ratificação dos atos.', ['Distinguir representante e titular da ação.', 'Ratificação precisa ser válida por quem tem poderes.'], 'Não usar ratificação para criar legitimidade de parte inexistente ou reviver direito extinto.', 'Representação irregular é regularizada e atos ratificados validamente.', 'Pessoa sem direito material de ação não o adquire porque chama documento de ratificação.', ['Representante e titular são iguais? Não.', 'Ratificação pode sanar representação na hipótese? Sim.'], 'Ratificação','Confirmação válida dos atos por quem pode praticá-los.')
add(569,'Omissões acusatórias podem ser supridas antes de sentença final, respeitadas defesa, correlação e iniciativa atual.', ['Não converter suprimento em alteração factual sem aditamento.', 'Portaria/flagrante de contravenção: referência histórica não restaura ação policial.', 'Examinar requisitos e limites do defeito.'], 'Antes da sentença não significa licença para condenar por fato surpresa.', 'Dado omitido é regularizado com garantias pertinentes.', 'Novo elemento acusatório exige procedimento de aditamento e oportunidade de defesa.', ['Suprimento dispensa contraditório? Não.', 'Portaria policial vira acusação penal válida por si? Não.'], 'Suprimento de omissão','Correção processual sujeita aos limites da acusação.')
add(570,'Comparecimento antes da consumação pode sanar vício de citação/intimação/notificação, mas juiz adia ou suspende se houver risco ao direito.', ['Mesmo comparecimento só para arguir pode produzir efeito previsto.', 'Ciência não substitui tempo necessário à defesa quando prejudicada.'], 'Não usar presença para obrigar julgamento surpresa sem prazo defensivo útil.', 'Interessado comparece e tem condições de exercer direito adequadamente.', 'Comparece no último momento sem acesso: juízo examina adiamento para evitar prejuízo.', ['Comparecimento elimina sempre necessidade de adiar? Não.', 'Risco ao direito demanda providência judicial? Sim.'], 'Comparecimento saneador','Ciência efetiva com proteção ao exercício do direito.')
add(571,'Nulidades devem ser suscitadas oportunamente segundo fase e regime; remissões a artigos revogados não fixam prazos atuais.', ['500 e537 foram revogados: integrar alegações e atos atuais.', 'No plenário/audiência/sessão: arguir logo após ocorrência.', 'Vício após primeira instância: razões recursais ou momento indicado.', 'Distinguir nulidade, preclusão e garantias essenciais.'], 'Não decorar prazo inexistente do art.500/537 nem aguardar resultado para guardar vício conhecido como estratégia.', 'Defesa registra objeção ao surgir irregularidade em plenário.', 'Vício de instrução requer identificação do momento processual atual, não prazo de artigo eliminado.', ['Remissão restaura prazo revogado? Não.', 'Ocorrência em plenário exige arguição oportuna? Sim.'], 'Oportunidade da arguição','Momento de suscitar vício com registro e fundamento.')
add(572,'Vícios enumerados podem ser sanados por falta de arguição oportuna, finalidade alcançada ou aceitação dos efeitos.', ['Hipóteses do rol precisam de integração atual.', 'Não aplicar saneamento indistinto a falta absoluta de defesa.', 'Finalidade real do ato importa.'], 'Não afirmar que qualquer nulidade se sana pelo silêncio de toda pessoa em qualquer hipótese.', 'Forma alternativa cumpre finalidade e não prejudica garantia no caso pertinente.', 'Ausência total de defensor não é banalizada como aceitação tácita.', ['Toda nulidade se sana sempre por silêncio? Não.', 'Finalidade alcançada pode importar? Sim.'], 'Saneamento delimitado','Convalidação nas hipóteses legalmente pertinentes.',[S523])
add(573,'Ato nulo não sanado é renovado ou retificado; nulidade alcança dependentes/consequentes diretos e juiz delimita extensão.', ['Não destruir atos independentes automaticamente.', 'Decisão identifica quais atos são atingidos.'], 'Anular um ato não significa anular toda causa sem demonstrar dependência.', 'Depoimento inválido é renovado e decisões diretamente dependentes são examinadas.', 'Documento independente válido não é eliminado só por integrar mesmos autos.', ['Juiz delimita extensão? Sim.', 'Todo ato independente cai automaticamente? Não.'], 'Extensão da nulidade','Alcance ligado à dependência processual.')
add(574,'Recursos são em regra voluntários; incisoII sobre absolvição sumária do júri exige integração à reforma de2008.', ['STJ reconhece superação do reexame obrigatório da absolvição sumária do júri.', 'Art.416 atual prevê apelação voluntária.', 'IncisoI descreve hipótese de concessão de habeas corpus no regime cabível.'], 'Não ensinar recurso de ofício da absolvição sumária pelo antigo art.411 como regra vigente.', 'Parte interessada pode recorrer por apelação da absolvição sumária atual.', 'Não exigir remessa automática apenas pela referência antiga do incisoII.', ['Absolvição sumária atual exige esse recurso de ofício antigo? Não.', 'Apelação do art.416 permanece? Sim.'], 'Voluntariedade e remessa','Distinção entre recurso da parte e hipóteses de reexame.',[JURY])
add(575,'Erro, falta ou omissão de funcionário não deve prejudicar seguimento ou apresentação tempestiva do recurso na hipótese prevista.', ['Demonstrar falha e circunstâncias.', 'Não converter em prorrogação livre por inércia da parte.'], 'A proteção não autoriza atribuir toda intempestividade à secretaria sem suporte.', 'Parte entrega no prazo, mas falha de registro impede andamento: prova do ocorrido importa.', 'Parte perde prazo por negligência própria não entra automaticamente na hipótese.', ['Falha funcional pode proteger recurso? Sim.', 'Basta alegar falha sem demonstrar? Não.'], 'Falha de processamento','Irregularidade funcional que não deve onerar recorrente diligente.')
add(576,'MP não pode desistir de recurso que já interpôs.', ['Distinguir não recorrer e desistir depois.', 'Opinião em fase posterior não é retirada automática do recurso.'], 'Não confundir manifestação jurídica com autorização para apagar recurso interposto.', 'MP recorre e depois revê avaliação; recurso não é desistido livremente.', 'Decidir não interpor antes é situação diferente da desistência vedada.', ['MP pode desistir livremente após interpor? Não.', 'Não recorrer inicialmente é a mesma situação? Não.'], 'Indisponibilidade recursal do MP','Vedação de desistência do recurso interposto.')
add(577,'Legitimados enumerados podem recorrer, mas precisam de interesse em modificar decisão.', ['MP, querelante, réu, procurador ou defensor.', 'Outras participações legais dependem de previsão específica.', 'Interesse não se reduz sempre a valor econômico.'], 'Legitimidade formal não dispensa utilidade jurídica do pedido.', 'Defesa busca corrigir decisão prejudicial ao acusado.', 'Parte sem interesse na alteração não tem recurso admitido só por ser parte.', ['Legitimidade dispensa interesse? Não.', 'Defensor está previsto? Sim.'], 'Interesse recursal','Utilidade de obter reforma ou modificação.')
add(578,'Interposição por petição ou termo assinado; impossibilidade de assinatura do réu admite assinatura a rogo com duas testemunhas.', ['Registros de entrega e encaminhamento da secretaria.', 'Integrar protocolo eletrônico e garantias disciplinares atuais.', 'Sanção histórica não dispensa procedimento adequado.'], 'Não exigir forma física exclusiva em sistema eletrônico nem impor punição disciplinar sumária.', 'Réu sem capacidade de assinar usa termo a rogo na forma prevista.', 'Petição protocolada eletronicamente deve ser analisada pelo regime válido do órgão.', ['A rogo exige duas testemunhas? Sim.', 'Texto elimina protocolo eletrônico válido? Não.'], 'Interposição formal','Ato de apresentar recurso e registrar sua tempestividade.')
add(579,'Fungibilidade penal admite recurso inadequado como cabível, sem má-fé e com prazo e requisitos do correto.', ['Tema1219/STJ,2024: erro grosseiro por si não impede fungibilidade penal.', 'Respeitar tempestividade do recurso cabível.', 'Juiz processa pelo rito adequado na hipótese legal.'], 'Não repetir regra antiga de proibição universal por erro grosseiro; nem usar fungibilidade para salvar recurso fora do prazo pertinente.', 'RESE apresentado no prazo e com requisitos pode ser tratado como apelação na hipótese do precedente.', 'Má-fé ou falta de pressupostos do correto exigem análise distinta.', ['Erro grosseiro isolado impede sempre no penal? Não.', 'Prazo do recurso cabível importa? Sim.'], 'Fungibilidade penal','Aproveitamento sujeito aos pressupostos atuais.',[FUNG])
add(580,'Resultado favorável de recurso de um corréu pode beneficiar outros se motivo não for exclusivamente pessoal.', ['Mesma razão objetiva pertinente.', 'Remissão ao antigo art.25/CP não altera regra de extensão.', 'Não estender condição individual automaticamente.'], 'Benefício ligado só à pessoa não se comunica a todo corréu.', 'Reconhecimento de inexistência do fato pode repercutir nos demais em situação equivalente.', 'Circunstância pessoal de um acusado não se transfere por mera coautoria.', ['Motivo exclusivamente pessoal comunica sempre? Não.', 'Fundamento objetivo pode aproveitar outros? Sim.'], 'Efeito extensivo','Aplicação do resultado a corréus na mesma razão jurídica.')
add(581,'RESE cabe nas hipóteses legais, com atualização do rito do júri, ANPP e execução penal.', ['Rejeição acusatória, incompetência, exceções procedentes salvo suspeição, pronúncia.', 'Fiança/liberdade, extinção da punibilidade, habeas corpus e demais hipóteses pertinentes.', 'IncisoXXV: recusa de homologação de ANPP.', 'Impronúncia/absolvição sumária: apelação do art.416; incisoVI revogado.', 'Decisões do juízo da execução seguem agravo da LEP197, não aplicação automática de incisos antigos.', 'Não restaurar conversão automática da multa em prisão.'], 'Taxatividade e interpretação precisam de hipótese e regime; não usar lista residual para ensinar recurso atual incorreto na execução.', 'Recusa judicial de homologação do ANPP é hipótese de RESE.', 'Revogação de livramento pelo juízo da execução exige examinar agravo em execução, não memorizar incisoXII isolado.', ['ANPP recusado na homologação tem hipótese expressa? Sim.', 'Impronúncia usa incisoVI revogado? Não.'], 'Cabimento do RESE','Recurso legalmente delimitado e integrado às normas posteriores.',[LEP])
add(582,'Texto histórico de Tribunais de Apelação e exceções deve ser integrado à competência recursal constitucional e organização atuais.', ['Não tratar nome antigo como órgão autônomo contemporâneo.', 'HypóteseXIV indica presidente no texto; verificar órgão competente atual.', 'Competência depende de decisão, autoridade e regime aplicável.'], 'Não concluir que todo habeas corpus ou fiança pode ser revisto por qualquer juízo só pela exceção histórica.', 'Parte identifica órgão competente para decisão recorrida no sistema atual.', 'Usar nome antigo sem verificar competência pode encaminhar recurso ao destinatário errado.', ['Nome histórico define sozinho órgão atual? Não.', 'É preciso identificar competência pertinente? Sim.'], 'Competência recursal','Órgão apto segundo sistema constitucional e normas atuais.')
